function frame(now){if(!running)return;const dt=Math.min(.04,(now-last)/1000||0);last=now;if(!paused){elapsed+=dt;pulse+=dt;power=Math.max(0,power-dt);boost=Math.max(0,boost-dt);player.speed=(15+Math.min(level-1,5)*.8)*(boost>0?1.32:1);player.mouth+=dt*22;stepActor(player,dt,true);for(const g of ghosts){g.wait=Math.max(0,g.wait-dt);if(g.wait===0)stepActor(g,dt);}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt;if(p.life<=0)particles.splice(i,1);}
for(const g of ghosts){if(g.wait>0)continue;const dx=g.x-player.x,dy=g.y-player.y;if(dx*dx+dy*dy<.34){if(power>0){score+=200;g.x=g.home.x;g.y=g.home.y;g.wait=.6;burst(g.x,g.y,'#62f7ff',12);updateHud();}else{loseLife();break;}}}
if(pellets<=0&&running){level++;resetMap();initActors();player.speed+=1;showToast('SECTOR '+String(level).padStart(2,'0'));updateHud();}}
draw();if(running)requestAnimationFrame(frame);}
resetMap();initActors();resize();updateHud();
})();
</script>
